function raceCard(p){const r=p.races,bets=p.bets||[],decisions=p.bet_decisions||[],incomplete=p.action==="bet"&&!bets.length,stake=bets.reduce((n,b)=>n+Number(b.stake),0),returned=bets.reduce((n,b)=>n+Number(settlementOf(b)?.return_amount||0),0);return `<article class="race"><div class="race-heading"><div><small>${new Date(r.start_time).toLocaleDateString("ja-JP")}・${r.surface==="turf"?"芝":"ダート"} ${r.distance||"—"}m</small><div><strong>${esc(r.track)} ${r.race_number}R</strong><span>${esc(r.race_name)}</span></div></div><span class="outcome ${incomplete?"failed":p.action}">${incomplete?"購入保存エラー":p.action==="bet"?"ペーパーBET":"AI見送り"}</span></div>${incomplete?`<div class="delay-warning">購入判断後の保存に失敗しました。AIの見送りではありません。</div>`:""}<div class="prediction-meta"><span>Gemini信頼度 ${Number(p.confidence||0)}%</span><span>T-20情報で判断</span></div>${predictionMarks(p)}<p class="race-copy">${esc(p.reason)}</p>${bets.map(b=>`<div class="bet"><b>${betLabels[b.bet_type]||b.bet_type} ${b.combination.join("-")}</b><span>${yen(b.stake)}</span><small>予測時オッズ ${Number(b.odds_at_prediction).toFixed(1)}${b.expected_value==null?"":` / 参考EV ${Number(b.expected_value).toFixed(2)}`}</small></div>`).join("")}<div class="decision-link" data-open-call="${p.ai_call_id}">Geminiへの入力と判断根拠を見る <b>→</b></div><div class="race-result"><span>投資 ${yen(stake)}</span><span>払戻 ${r.status==="finished"?yen(returned):"—"}</span><span>技術検証 ${decisions.length}件</span></div></article>`}
function renderAnalytics(){const stats=accounts.map(a=>({...a,...RaceAnalytics.strategyStats(allBets,a.strategy)})),tot=RaceAnalytics.validationStats(allBets);$("#analysis-metrics").innerHTML=[["検証済み馬券",tot.count],["確率誤差",pct(tot.calibrationGap*100)],["Brierスコア",tot.brierScore.toFixed(3)],["AI処理履歴",aiCalls.length]].map(x=>`<div class="metric"><small>${x[0]}</small><strong>${x[1]}</strong></div>`).join("");$("#analysis-table").innerHTML=stats.map(a=>`<tr><td><span class="badge ${a.strategy}">${labels[a.strategy]}</span></td><td>${yen(a.staked)}</td><td>${yen(a.returned)}</td><td class="${a.profit>=0?"positive":"negative"}">${yen(a.profit)}</td><td>${pct(a.roi)}</td><td>${pct(a.predictedRate*100)}</td><td>${pct(a.observedRate*100)}</td><td>${pct(a.calibrationGap*100)}</td><td>${a.brierScore.toFixed(3)}</td></tr>`).join("")}
function filteredCalls(){const purpose=$("#trace-purpose").value,strategy=$("#trace-strategy").value;return aiCalls.filter(c=>(purpose==="all"||c.purpose===purpose)&&(strategy==="all"||c.strategy===strategy))}
function renderCalls(){const rows=filteredCalls(),names={screening:"候補レースを選定",prediction:"最終判断",correction:"回答を再確認",audit:"監査"};$("#call-list").innerHTML=rows.map(c=>{const related=predictions.filter(p=>p.ai_call_id===c.id),race=related[0]?.races,bets=related.flatMap(p=>p.bets||[]),incomplete=related.some(p=>p.action==="bet"&&!(p.bets||[]).length),action=incomplete?"保存失敗":bets.length?"購入":related.length?"見送り":names[c.purpose]||c.purpose;return `<button class="call-item ${selectedCall===c.id?"active":""}" data-ai-call="${c.id}"><span><em class="decision-chip ${incomplete?"failed":bets.length?"buy":related.length?"skip":"process"}">${action}</em><time>${clock(c.requested_at)}</time></span><strong>${race?`${esc(race.track)} ${race.race_number}R`:names[c.purpose]||c.purpose}</strong><small class="call-race-name">${race?esc(race.race_name):c.purpose==="screening"?"本日の全レースを比較":"Gemini AI処理"}</small><small>${c.status==="succeeded"?"✓ AI応答完了":"処理状態: "+esc(c.status)}・${Number(c.input_tokens||0).toLocaleString()} tokens</small></button>`}).join("")||empty("条件に一致するAI処理はありません")}
function modelAnswer(response){const text=response?.candidates?.[0]?.content?.parts?.map(p=>p.text).filter(Boolean).join("\n");if(!text)return null;try{return JSON.parse(text)}catch{return text}}
function promptPayload(prompt){const value=String(prompt||""),marker="INPUT_JSON=" ,at=value.lastIndexOf(marker);if(at>=0){try{return JSON.parse(value.slice(at+marker.length))}catch{}}for(let i=value.length-1;i>=0;i--){if(value[i]!=="["&&value[i]!=="{")continue;try{return JSON.parse(value.slice(i))}catch{}}return null}
function inputView(call){const payload=promptPayload(call.request_json?.prompt);if(!payload)return `<div class="legacy-note">入力データを読み取れませんでした。</div>`;if(call.purpose==="screening"){const rows=Array.isArray(payload)?payload:(payload.races||[]);return `<div class="input-summary"><span><b>${rows.length}</b>件を比較</span><span><b>単勝</b>市場人気を確認</span></div><div class="data-grid">${rows.map(screeningInputCard).join("")}</div>`}const rows=Array.isArray(payload)?payload:[payload];return rows.map(r=>raceInputCard(r)).join("")}
function screeningInputCard(row){const race=row.race||row,market=row.market||{},runners=market.runners||[],roughness=(row.evidence||[]).find(x=>x.source==="uma-x")?.raceMetrics?.roughness;return `<article class="data-card"><b>${esc(race.track||"分析結果")} ${race.race_number||race.raceNumber||""}R</b><strong>${esc(race.race_name||race.raceName||row.race_id||"")}</strong><small>${race.surface==="turf"?"芝":race.surface==="dirt"?"ダート":esc(race.surface||"")} ${race.distance?`・${race.distance}m`:""}</small><small>市場人気：${market.status==="available"?`${runners.length}頭・${esc(market.captured_at||"")}`:"取得不可"}</small>${runners.length?`<small>上位 ${runners.slice(0,4).map(x=>`${x.popularity||"—"}人気 ${x.horse_number}番 ${Number(x.win_odds).toFixed(1)}倍`).join(" / ")}</small>`:""}${roughness?`<small>ウマークス荒度 ${roughness}/18（オッズ由来）</small>`:""}</article>`}
function raceInputCard(row){const race=row.race||{},entries=race.entries||row.entries||[],evals=row.independent_evaluation?.evaluations||row.evaluations||[],odds=row.valid_market_odds||row.odds||[],byNumber=new Map(entries.map(e=>[e.horseNumber,e])),budget=row.wager_budget||{};return `<article class="input-race"><div class="input-race-head"><div><b>${esc(race.track)} ${race.raceNumber||race.race_number||""}R</b><strong>${esc(race.raceName||race.race_name||"")}</strong></div><span>${race.surface==="turf"?"芝":race.surface==="dirt"?"ダート":esc(race.surface||"—")} ${race.distance||"—"}m</span></div>${budget.maximum_total_stake!=null?`<div class="input-summary"><span><b>${yen(budget.maximum_total_stake)}</b>今回の上限</span><span><b>${esc(row.capital_context?.capital_mode||"normal")}</b>資金モード</span></div>`:""}<h4>過去走から整理した参考評価</h4><div class="table-wrap compact"><table><thead><tr><th>馬</th><th>総合</th><th>能力</th><th>適性</th><th>状態</th><th>展開</th><th>推定勝率</th><th>品質</th></tr></thead><tbody>${evals.sort((a,b)=>b.overallScore-a.overallScore).map(e=>{const entry=byNumber.get(e.horseNumber)||{};return `<tr><td><b>${e.horseNumber} ${esc(e.horseName||entry.horseName)}</b><small>${esc(entry.jockey||"")}</small></td><td><strong>${Number(e.overallScore).toFixed(1)}</strong></td><td>${Number(e.abilityScore).toFixed(1)}</td><td>${Number(e.suitabilityScore).toFixed(1)}</td><td>${Number(e.conditionScore).toFixed(1)}</td><td>${Number(e.raceContextScore).toFixed(1)}</td><td>${pct(Number(e.estimatedWinProbability)*100)}</td><td>${pct(Number(e.dataQuality)*100)}<small>${e.sampleSize}走</small></td></tr>`}).join("")}</tbody></table></div><details><summary>AIが比較した有効オッズ ${odds.length}件</summary><div class="odds-grid">${odds.map(o=>`<span><b>${betLabels[o.type]||o.type} ${(o.horses||[]).join("-")}</b>${Number(o.odds).toFixed(1)}${o.oddsMax?`〜${Number(o.oddsMax).toFixed(1)}`:""}倍${o.popularity?`・${o.popularity}人気`:""}</span>`).join("")}</div></details></article>`}
async function openCall(id){selectedCall=id;renderCalls();const el=$("#trace-detail");el.innerHTML='<div class="loading">監査データを読み込んでいます…</div>';try{const [callRows,preds]=await Promise.all([api("ai_calls",`id=eq.${encodeURIComponent(id)}&select=*`),api("predictions",`ai_call_id=eq.${encodeURIComponent(id)}&select=id,strategy,action,confidence,reason,raw_response,races(id,track,race_number,race_name,start_time),bets(*),bet_decisions(*)&order=predicted_at`)]),call=callRows[0];if(!call)throw new Error("AI処理が見つかりません");renderTrace(call,preds)}catch(e){el.innerHTML=empty(e.message)}}
function renderTrace(call,preds){const answer=modelAnswer(call.response_json),decisions=preds.flatMap(p=>(p.bet_decisions||[]).map(d=>({...d,race:p.races,prediction:p}))),purchased=decisions.filter(d=>d.decision!=="rejected").length,rejected=decisions.filter(d=>d.decision==="rejected").length,bets=preds.flatMap(p=>p.bets||[]),primary=preds[0],selection=primary?(pipelineItems.find(x=>x.races?.id===primary.races.id)||selections.find(x=>x.race_id===primary.races.id)):null,selectionReason=selection?.selection_reason||selection?.reason,verdict=bets.length?"購入":preds.length?"見送り":"候補を選定";$("#trace-detail").innerHTML=`<div class="trace-title"><div><span class="decision-chip ${bets.length?"buy":preds.length?"skip":"process"}">${verdict}</span><h2>${primary?`${esc(primary.races.track)} ${primary.races.race_number}R ${esc(primary.races.race_name)}`:call.purpose==="prediction"?"発走前の最終判断":"本日の候補レース選定"}</h2><p>${dt(call.requested_at)}・Geminiによる判断</p></div><div class="trace-summary"><b>${purchased}</b><small>購入</small><b>${rejected}</b><small>AI見送り</small></div></div>
<section class="decision-overview"><div><p class="eyebrow">DECISION</p><h3>${bets.length?`${bets.length}点を購入`:preds.length?"このレースは見送り":"対象レースを絞り込み"}</h3><p>${primary?esc(primary.reason):"全レースを比較し、直前判断へ進める候補を選びました。"}</p></div>${primary?`<div class="confidence-ring" style="--confidence:${Number(primary.confidence||0)*3.6}deg"><strong>${Number(primary.confidence||0)}<small>%</small></strong><span>信頼度</span></div>`:""}${primary?predictionMarks(primary):""}${bets.length?`<div class="overview-tickets">${bets.map(b=>`<span><b>${betLabels[b.bet_type]||b.bet_type} ${(b.combination||[]).join("-")}</b>${yen(b.stake)}</span>`).join("")}</div>`:""}</section>
${primary?`<section class="reason-comparison"><div><small>候補に選んだ理由</small><b>${esc(selectionReason||"選定理由の記録なし")}</b></div><span>→</span><div><small>直前の最終判断</small><b>${esc(primary.reason||"最終判断理由の記録なし")}</b></div></section>`:""}
<div class="detail-divider"><span>詳しい判断過程</span></div>
<section class="trace-step"><div class="step-no">1</div><div><p class="eyebrow">AI INPUT</p><h3>AIに渡したデータ</h3><p>対象レース、出走馬の評価、予測確率、データ品質、オッズを読みやすく整理しています。</p><div class="hashes"><span>対象データ改ざん検知済み</span><span>${Number(call.input_tokens||0).toLocaleString()} tokens</span></div>${inputView(call)}</div></section>
<section class="trace-step"><div class="step-no">2</div><div><p class="eyebrow">AI RESPONSE</p><h3>AIの回答</h3>${renderAnswer(answer,preds)}</div></section>
<section class="trace-step"><div class="step-no">3</div><div><p class="eyebrow">SYSTEM GUARD</p><h3>購入条件の確認</h3><p>プログラムはAIの予想を作り直しません。実在する馬・対応券種・100円単位・残高・正常オッズに加え、複数点的中時を含む回収割れがないかを確認します。</p>${decisions.length?decisions.map(decisionCard).join(""):`<div class="legacy-note">${call.purpose==="screening"?"この処理はレース候補の選定です。最終判断は発走約20分前にGeminiが行います。":"Geminiはこのレースを見送りました。"}</div>`}</div></section>
<section class="trace-step final"><div class="step-no">4</div><div><p class="eyebrow">FINAL RESULT</p><h3>最終結果</h3>${preds.length?preds.map(p=>`<div class="final-row"><b>${esc(p.races.track)} ${p.races.race_number}R ${esc(p.races.race_name)}</b><span>${p.action==="bet"&&(p.bets||[]).length?`${p.bets.length}点・${yen(p.bets.reduce((n,b)=>n+Number(b.stake),0))}`:"見送り"}</span></div>`).join(""):"後続の予測処理で購入を決定します。"}</div></section>`}
function renderAnswer(a,preds){if(!a)return `<div class="legacy-note">Geminiから有効な回答を取得できませんでした。</div>`;if(typeof a==="string")return `<div class="legacy-note">${esc(a)}</div>`;if(Array.isArray(a.assessments)){const chosen=a.assessments.filter(x=>x.selected);return `<div class="answer-box"><div><small>AIが選んだレース</small><strong>${chosen.length}件</strong></div><div><small>全体判断</small><strong>${esc(a.overall_reason||"—")}</strong></div></div>${a.assessments.sort((x,y)=>(x.selected?0:1)-(y.selected?0:1)||Number(x.priority||99)-Number(y.priority||99)).map(x=>`<div class="selection-answer"><span class="badge single">${x.selected?`選択 ${x.priority}`:"非選択"}</span><b>${esc(x.race_id)}</b><strong>予算比率 ${Number(x.budget_weight||0)}</strong><p>${esc(x.selection_reason)}</p><small>比較判断：${esc(x.decision_reason)}</small>${(x.conflicts||[]).length?`<small>反対材料：${esc(x.conflicts.join(" / "))}</small>`:""}${(x.risks||[]).length?`<small>リスク：${esc(x.risks.join(" / "))}</small>`:""}</div>`).join("")}`}if(a.race_id||a.action){return `<article class="ai-prediction"><div><b>${a.action==="BET"?"AIが購入":"AIが見送り"}</b><span>信頼度 ${esc(a.overall_confidence||"—")}</span></div><p>${esc(a.reason)}</p><div class="rollover-plan"><b>独立指数の扱い</b><span>${esc(a.independent_basis||"記録なし")}</span></div><div class="rollover-plan"><b>外部評価の扱い</b><span>${esc(a.external_consensus_assessment||"記録なし")}</span></div><div class="rollover-plan"><b>予算判断</b><span>${esc(a.budget_reason||"記録なし")}</span></div>${(a.contradicting_evidence||[]).map(x=>`<small class="caveat">反対材料：${esc(x)}</small>`).join("")}${(a.data_caveats||[]).map(x=>`<small class="caveat">注意点：${esc(x)}</small>`).join("")}${(a.bets||[]).map(b=>`<div class="ai-bet"><b>${b.decision==="BUY"?"購入":"見送り"}・${betLabels[b.bet_type]||b.bet_type} ${(b.horses||[]).join("-")}</b><span>${b.decision==="BUY"?yen(b.stake):"0円"} / 的中推定 ${pct(Number(b.hit_probability||0)*100)}</span><p>${esc(b.reason)}</p><small>オッズ評価：${esc(b.odds_assessment)}</small><small>金額理由：${esc(b.stake_reason)}</small><small>最大リスク：${esc(b.risk)}</small></div>`).join("")}</article>`}const list=a.predictions||[];return list.length?list.map(x=>renderAnswer(x,preds)).join(""):`<details><summary>GeminiのJSON回答</summary><pre>${esc(JSON.stringify(a,null,2))}</pre></details>`}
function decisionCard(d){const ok=d.decision!=="rejected",aiRejected=d.reason_code==="AI_REJECTED",label=ok?"AI購入":aiRejected?"AI見送り":"購入条件エラー",odds=Number(d.odds),ev=Number(d.expected_value);return `<article class="decision ${d.decision}"><div class="decision-state">${ok?"✓":aiRejected?"—":"×"}<span>${label}</span></div><div><b>${betLabels[d.bet_type]||d.bet_type} ${(d.combination||[]).join("-")}</b><p>${esc(d.reason_detail||"購入条件を確認しました")}</p><div class="checks"><span>AI決定額 <b>${yen(d.proposed_stake)}</b></span><span>保存額 <b>${yen(d.final_stake)}</b></span>${Number.isFinite(odds)?`<span>最低オッズ <b>${odds.toFixed(1)}倍</b></span>`:""}${Number.isFinite(ev)?`<span>監査EV <b>${ev.toFixed(2)}</b></span>`:""}<span>システム確認 <b>形式・残高・オッズ・ガミ防止</b></span></div></div></article>`}
function renderOperations(){const pipeline=pipelineItems.slice(0,40).map(x=>`<div class="audit-row"><b>${x.races?`${new Date(x.races.start_time).toLocaleDateString("ja-JP",{month:"numeric",day:"numeric"})} ${esc(x.races.track)} ${x.races.race_number}R`:dt(x.updated_at)}</b><span>${stateLabels[x.state]||esc(x.state)}<small>${x.races?esc(x.races.race_name):""}${x.selection_reason?` / ${esc(x.selection_reason)}`:""}${x.last_error?` / ${esc(x.last_error)}`:""}</small></span><em class="status ${x.state==="failed"||x.state==="invalid_output"?"failed":x.state==="completed"||x.state==="final_decided"?"succeeded":""}">${stateLabels[x.state]||x.state}</em></div>`).join("");const history=batches.map(b=>`<div class="audit-row"><b>${dt(b.started_at)}</b><span>${esc(b.parser_version)}<small>${b.races_fetched}レース / API ${b.api_requests}回${b.error_message?` / ${esc(b.error_message)}`:""}</small></span><em class="status ${b.status}">${b.status}</em></div>`).join("");$("#audit-list").innerHTML=pipeline||history||empty("履歴はありません")}
function empty(s){return `<div class="empty-state"><span>${esc(s)}</span></div>`}function showError(s){$("#error").hidden=false;$("#error").textContent=s}function logout(){disconnectRealtime();localStorage.removeItem("race-lab-session");session=null;$("#auth").classList.remove("hidden")}
let metricHelpTrigger=null;function openMetricHelp(trigger){const pop=$("#metric-help-popover");if(!pop)return;metricHelpTrigger=trigger;pop.querySelector("h3").textContent=trigger.dataset.helpTitle;pop.querySelector("p").textContent=trigger.dataset.helpCopy;pop.querySelector("strong").textContent=trigger.dataset.helpCurrent;pop.hidden=false;pop.querySelector("[data-metric-help-close]")?.focus()}function closeMetricHelp(){const pop=$("#metric-help-popover");if(!pop||pop.hidden)return;pop.hidden=true;metricHelpTrigger?.focus();metricHelpTrigger=null}
document.addEventListener("click",e=>{const page=e.target.closest("[data-page]"),strategy=e.target.closest("[data-strategy]"),card=e.target.closest("[data-open-strategy]"),call=e.target.closest("[data-ai-call],[data-open-call]"),raceTarget=e.target.closest("[data-scroll-race]"),pageTarget=e.target.closest("[data-page-target]"),refreshNow=e.target.closest("[data-refresh-now]"),pushToggle=e.target.closest("[data-push-toggle]"),metricHelp=e.target.closest("[data-metric-help]"),metricClose=e.target.closest("[data-metric-help-close]");if(page){document.querySelectorAll("[data-page],.page").forEach(x=>x.classList.remove("active"));page.classList.add("active");$(`#${page.dataset.page}`).classList.add("active");$("#page-title").textContent=page.textContent.trim();$("#page-title").hidden=page.dataset.page==="dashboard"}if(strategy){activeStrategy=strategy.dataset.strategy;renderToday()}if(card){activeStrategy=card.dataset.openStrategy;document.querySelector('[data-page="today"]').click()}if(call){document.querySelector('[data-page="trace"]').click();openCall(call.dataset.aiCall||call.dataset.openCall)}if(raceTarget){const target=document.getElementById(`timeline-race-${raceTarget.dataset.scrollRace}`);if(target){target.open=true;requestAnimationFrame(()=>target.scrollIntoView({behavior:"smooth",block:"center"}));target.classList.add("focus-pulse");setTimeout(()=>target.classList.remove("focus-pulse"),1600)}}if(pageTarget)document.querySelector(`[data-page="${pageTarget.dataset.pageTarget}"]`)?.click();if(refreshNow)load();if(pushToggle)togglePush();if(metricHelp)openMetricHelp(metricHelp);if(metricClose||e.target.id==="metric-help-popover")closeMetricHelp()});
document.addEventListener("keydown",e=>{if(e.key==="Escape")closeMetricHelp()});
let installPrompt=null;window.addEventListener("beforeinstallprompt",event=>{event.preventDefault();installPrompt=event;$("#pwa-install").hidden=false});$("#pwa-install").addEventListener("click",async()=>{if(!installPrompt)return;await installPrompt.prompt();installPrompt=null;$("#pwa-install").hidden=true});window.addEventListener("appinstalled",()=>{$("#pwa-install").hidden=true;installPrompt=null});
if("serviceWorker" in navigator){window.addEventListener("load",async()=>{try{const registration=await navigator.serviceWorker.register("./sw.js");const showUpdate=worker=>{if(!worker)return;const toast=$("#pwa-update");toast.hidden=false;toast.querySelector("button").onclick=()=>worker.postMessage({type:"SKIP_WAITING"})};if(registration.waiting)showUpdate(registration.waiting);registration.addEventListener("updatefound",()=>{const worker=registration.installing;worker?.addEventListener("statechange",()=>{if(worker.state==="installed"&&navigator.serviceWorker.controller)showUpdate(worker)})});let refreshing=false;navigator.serviceWorker.addEventListener("controllerchange",()=>{if(refreshing)return;refreshing=true;location.reload()})}catch(error){console.warn("PWA registration failed",error)}})}
setInterval(()=>{if(session&&pipelineItems.length)renderDashboard()},30000);setInterval(()=>{if(session&&!document.hidden)load()},180000);
