[$("#trace-purpose"),$("#trace-strategy")].forEach(x=>x.addEventListener("change",renderCalls));$("#logout").addEventListener("click",logout);$("#auth-form").addEventListener("submit",async e=>{e.preventDefault();try{$("#auth-message").textContent="ログイン中…";saveSession(await auth("token?grant_type=password",{email:$("#email").value,password:$("#password").value}));$("#auth").classList.add("hidden");$("#auth-message").textContent="";connectRealtime();load()}catch(x){$("#auth-message").textContent=x.message}});$("#signup").addEventListener("click",async()=>{try{$("#auth-message").textContent="作成中…";const d=await auth("signup",{email:$("#email").value,password:$("#password").value,data:{display_name:$("#email").value.split("@")[0]}});$("#auth-message").textContent=d.access_token?"作成しました":"確認メールを送信しました"}catch(x){$("#auth-message").textContent=x.message}});$("#today-label").textContent=new Date().toLocaleDateString("ja-JP",{year:"numeric",month:"long",day:"numeric",weekday:"long"});if(session){$("#auth").classList.add("hidden");ensureSession().then(()=>{connectRealtime();return load()}).catch(()=>logout())}
